/* ===================== ДВИЖОК ===================== */
const shuffle=a=>{a=a.slice();for(let i=a.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]];}return a;};
const LS={mast:{sub:"notes"},dd:{sub:"notes"}};

function lrRender(k){
  const st=LS[k], D=LEARN[k], el=document.getElementById("learn-"+k);
  const subs=[["notes","Конспект"],["quiz","Тест ("+D.quiz.length+")"],["tasks","Задачи ("+D.tasks.length+")"],["cards","Карточки ("+D.cards.length+")"]];
  let h=`<div class="card"><div class="seg lr-sub">${subs.map(([v,l])=>`<button data-v="${v}" class="${st.sub===v?"on":""}">${l}</button>`).join("")}</div>
    <p class="note" style="margin:8px 0 0">${D.src}</p></div><div class="lr-body"></div>`;
  el.innerHTML=h;
  el.querySelector(".lr-sub").onclick=e=>{const b=e.target.closest("button");if(!b)return;st.sub=b.dataset.v;lrRender(k);window.scrollTo({top:0});};
  const body=el.querySelector(".lr-body");
  ({notes:lrNotes,quiz:lrQuiz,tasks:lrTasks,cards:lrCards})[st.sub](k,body);
}

function lrNotes(k,body){
  const D=LEARN[k];
  body.innerHTML=`<div class="card"><div class="row"><button class="btn alt" id="nt-open">Развернуть всё</button><button class="btn alt" id="nt-close">Свернуть</button></div></div>`+
   D.notes.map(s=>`<details class="card note-sec"><summary style="font-size:16px;color:var(--ink)">${s.h}</summary><ul style="margin:8px 0 0;padding-left:20px">${s.i.map(x=>`<li style="margin:0 0 6px">${x}</li>`).join("")}</ul></details>`).join("");
  body.querySelector("#nt-open").onclick=()=>body.querySelectorAll("details").forEach(d=>d.open=true);
  body.querySelector("#nt-close").onclick=()=>body.querySelectorAll("details").forEach(d=>d.open=false);
}

function lrQuiz(k,body){
  const D=LEARN[k], st=LS[k];
  if(!st.q||st.q.done===undefined||st.q.restart){
    st.q={order:shuffle(D.quiz.map((_,i)=>i)),i:0,ok:0,wrong:[],ans:null,opts:null,done:false};
  }
  const Q=st.q;
  if(Q.i>=Q.order.length){
    const pct=Math.round(Q.ok/Q.order.length*100);
    body.innerHTML=`<div class="card"><h2>Результат: ${Q.ok} / ${Q.order.length} (${pct}%)</h2>
      <p class="score" style="color:${pct>=70?"var(--ok)":"var(--red)"}">${pct>=70?"Зачёт (≥70%)":"Ниже 70% — повторить"}</p>
      <div class="row"><button class="btn" id="qz-again">Заново</button>${Q.wrong.length?`<button class="btn alt" id="qz-wrong">Только ошибки (${Q.wrong.length})</button>`:""}</div></div>`+
      (Q.wrong.length?`<div class="card"><h3>Ошибки</h3>${Q.wrong.map(i=>`<div class="rec"><div class="rt"><b>${D.quiz[i].q}</b><br>✓ ${D.quiz[i].o[0]}</div><p class="note" style="margin:4px 0 0">${D.quiz[i].ex} <b>(${D.quiz[i].g})</b></p></div>`).join("")}</div>`:"");
    body.querySelector("#qz-again").onclick=()=>{Q.restart=true;st.q=null;lrRender(k);};
    const w=body.querySelector("#qz-wrong");
    if(w) w.onclick=()=>{st.q={order:shuffle(Q.wrong),i:0,ok:0,wrong:[],ans:null,opts:null,done:false};lrRender(k);};
    return;
  }
  const qi=Q.order[Q.i], q=D.quiz[qi];
  if(!Q.opts) Q.opts=shuffle(q.o.map((t,j)=>({t,c:j===0})));
  body.innerHTML=`<div class="card"><div class="row" style="justify-content:space-between"><span class="score">Вопрос ${Q.i+1}/${Q.order.length}</span><span class="score">✓ ${Q.ok}</span></div>
    <div style="height:6px;background:var(--chip);border-radius:3px;margin:8px 0"><div style="height:6px;width:${Q.i/Q.order.length*100}%;background:#c2185b;border-radius:3px"></div></div>
    <p style="font-size:17px;font-weight:700;margin:10px 0">${q.q}</p>
    <div class="topts">${Q.opts.map((o,j)=>`<button data-j="${j}">${o.t}</button>`).join("")}</div><div id="qz-fb"></div></div>`;
  const box=body.querySelector(".topts");
  const show=()=>{
    box.querySelectorAll("button").forEach((b,j)=>{b.disabled=true;if(Q.opts[j].c)b.classList.add("right");else if(j===Q.ans)b.classList.add("wrong");});
    const ok=Q.opts[Q.ans].c;
    body.querySelector("#qz-fb").innerHTML=`<div class="sec ${ok?"ok":"red"}" style="margin-top:12px"><h4>${ok?"Верно":"Неверно"}</h4><div class="rt">${q.ex} <b>(${q.g})</b></div></div>
      <button class="btn" id="qz-next" style="width:100%">Дальше →</button>`;
    body.querySelector("#qz-next").onclick=()=>{Q.i++;Q.ans=null;Q.opts=null;lrRender(k);};
  };
  if(Q.ans!==null) show();
  else box.onclick=e=>{const b=e.target.closest("button");if(!b)return;Q.ans=+b.dataset.j;if(Q.opts[Q.ans].c)Q.ok++;else Q.wrong.push(qi);show();};
}

function lrTasks(k,body){
  const D=LEARN[k], st=LS[k];
  if(st.t==null){
    body.innerHTML=D.tasks.map((t,i)=>`<div class="card" style="cursor:pointer" data-t="${i}"><h3 style="margin:0">Задача ${i+1}. ${t.t}</h3><p class="note" style="margin:6px 0 0">${t.intro.slice(0,110)}…</p><p class="note" style="margin:6px 0 0"><b>${t.steps.length} шага</b>${st.done&&st.done[i]!=null?` · результат ${st.done[i]}/${t.steps.length}`:""}</p></div>`).join("");
    body.onclick=e=>{const c=e.target.closest("[data-t]");if(!c)return;st.t=+c.dataset.t;st.s=0;st.ok=0;st.ans=null;st.opts=null;body.onclick=null;lrRender(k);window.scrollTo({top:0});};
    return;
  }
  body.onclick=null;
  const T=D.tasks[st.t];
  if(st.s>=T.steps.length){
    st.done=st.done||{};st.done[st.t]=st.ok;
    body.innerHTML=`<div class="card"><h2>${T.t}: ${st.ok} / ${T.steps.length}</h2><div class="row"><button class="btn" id="tk-list">К списку задач</button><button class="btn alt" id="tk-re">Пройти снова</button></div></div>`;
    body.querySelector("#tk-list").onclick=()=>{st.t=null;lrRender(k);};
    body.querySelector("#tk-re").onclick=()=>{st.s=0;st.ok=0;st.ans=null;st.opts=null;lrRender(k);};
    return;
  }
  const S=T.steps[st.s];
  if(!st.opts) st.opts=shuffle(S.o.map((t,j)=>({t,c:j===0})));
  const prev=T.steps.slice(0,st.s).map((p,i)=>`<div class="rec"><div class="rt"><b>Шаг ${i+1}.</b> ${p.q} → <span style="color:var(--ok);font-weight:700">${p.o[0]}</span></div></div>`).join("");
  body.innerHTML=`<div class="card"><div class="row" style="justify-content:space-between"><button class="btn alt" id="tk-back">← Задачи</button><span class="score">Шаг ${st.s+1}/${T.steps.length} · ✓ ${st.ok}</span></div>
    <h2 style="margin-top:12px">${T.t}</h2><div class="sec info"><div class="rt">${T.intro}</div></div>${prev?`<div class="sec plain">${prev}</div>`:""}
    <p style="font-size:17px;font-weight:700;margin:10px 0">Шаг ${st.s+1}. ${S.q}</p>
    <div class="topts">${st.opts.map((o,j)=>`<button data-j="${j}">${o.t}</button>`).join("")}</div><div id="tk-fb"></div></div>`;
  body.querySelector("#tk-back").onclick=()=>{st.t=null;lrRender(k);};
  const box=body.querySelector(".topts");
  const show=()=>{
    box.querySelectorAll("button").forEach((b,j)=>{b.disabled=true;if(st.opts[j].c)b.classList.add("right");else if(j===st.ans)b.classList.add("wrong");});
    const ok=st.opts[st.ans].c;
    body.querySelector("#tk-fb").innerHTML=`<div class="sec ${ok?"ok":"red"}" style="margin-top:12px"><h4>${ok?"Верно":"Разбор"}</h4><div class="rt">${S.ex}</div></div><button class="btn" id="tk-next" style="width:100%">${st.s+1<T.steps.length?"Следующий шаг →":"Итог →"}</button>`;
    body.querySelector("#tk-next").onclick=()=>{st.s++;st.ans=null;st.opts=null;lrRender(k);};
  };
  if(st.ans!==null) show();
  else box.onclick=e=>{const b=e.target.closest("button");if(!b)return;st.ans=+b.dataset.j;if(st.opts[st.ans].c)st.ok++;show();};
}

function lrCards(k,body){
  const D=LEARN[k], st=LS[k];
  if(!st.c) st.c={q:shuffle(D.cards.map((_,i)=>i)),flip:false,known:0};
  const C=st.c;
  if(!C.q.length){
    body.innerHTML=`<div class="card"><h2>Все ${D.cards.length} карточек выучены</h2><button class="btn" id="cd-re">Заново</button></div>`;
    body.querySelector("#cd-re").onclick=()=>{st.c=null;lrRender(k);};return;
  }
  const [f,b]=D.cards[C.q[0]];
  body.innerHTML=`<div class="card"><div class="row" style="justify-content:space-between"><span class="score">Осталось: ${C.q.length}</span><span class="score">Знаю: ${C.known}/${D.cards.length}</span></div>
    <div id="cd" style="margin:12px 0;min-height:180px;border:2px solid ${C.flip?"#0b5d1e":"var(--line)"};border-radius:14px;display:flex;flex-direction:column;align-items:center;justify-content:center;padding:18px;text-align:center;cursor:pointer;background:${C.flip?"var(--ok-bg)":"var(--card)"}">
      <div style="font-size:19px;font-weight:800">${f}</div>
      ${C.flip?`<div style="font-size:18px;margin-top:12px;font-weight:600">${b}</div>`:`<div class="note" style="margin-top:12px">нажми, чтобы перевернуть</div>`}</div>
    ${C.flip?`<div class="row"><button class="btn alt" id="cd-again" style="flex:1">↻ Повторить</button><button class="btn" id="cd-know" style="flex:1;background:#0b5d1e">✓ Знаю</button></div>`:""}</div>`;
  body.querySelector("#cd").onclick=()=>{C.flip=!C.flip;lrRender(k);};
  if(C.flip){
    body.querySelector("#cd-again").onclick=()=>{C.q.push(C.q.shift());C.flip=false;lrRender(k);};
    body.querySelector("#cd-know").onclick=()=>{C.q.shift();C.known++;C.flip=false;lrRender(k);};
  }
}
lrRender("mast");lrRender("dd");
